if doc.get("package") != "sk.meteor.dream" or doc.get(ns+"versionCode") != "3" or doc.get(ns+"versionName") != "0.1.2":
    raise SystemExit("Expected the original private Meteor Dream 0.1.2 archive; signing files were not changed.")
files = json.loads(r'''{"app/src/main/java/sk/meteor/dream/LaunchRules.java":"package sk.meteor.dream;\npublic final class LaunchRules {\n public static String reason(boolean enabled,boolean target,String token,String used){\n  if(!enabled)return \"DISABLED\";\n  if(!target)return \"MISSING_METEOR\";\n  if(token==null||token.length()==0)return \"UNKNOWN_BOOT\";\n  if(token.equals(used))return \"ALREADY_ATTEMPTED\";\n  return \"READY\";\n }\n private LaunchRules(){}\n}\n","app/src/main/java/sk/meteor/dream/LaunchPolicy.java":"package sk.meteor.dream;\nimport android.content.Context;\nimport android.content.SharedPreferences;\nimport android.os.SystemClock;\npublic final class LaunchPolicy {\n static synchronized String token(Context c){\n  SharedPreferences p=DreamTools.prefs(c);\n  long now=SystemClock.elapsedRealtime(),old=p.getLong(\"observed_elapsed\",-1);\n  String generation=p.getString(\"boot_generation\",\"initial\");\n  if(old>=0&&now<old){generation=java.util.UUID.randomUUID().toString();p.edit().putString(\"boot_generation\",generation).commit();DreamTools.log(c,\"Zistený pokles času od štartu; nový reštart.\");}\n  p.edit().putLong(\"observed_elapsed\",now).commit();\n  return DreamTools.boot(c)+\":\"+generation;\n }\n static String reason(Context c){return LaunchRules.reason(DreamTools.prefs(c).getBoolean(\"enabled\",true),DreamTools.meteor(c)!=null,token(c),DreamTools.prefs(c).getString(\"used_token\",\"\"));}\n static synchronized boolean claim(Context c){\n  String token=token(c);\n  String reason=LaunchRules.reason(DreamTools.prefs(c).getBoolean(\"enabled\",true),DreamTools.meteor(c)!=null,token,DreamTools.prefs(c).getString(\"used_token\",\"\"));\n  if(!\"READY\".equals(reason)){DreamTools.log(c,\"Automatický pokus preskočený: \"+reason);return false;}\n  boolean ok=DreamTools.prefs(c).edit().putString(\"used_token\",token).putInt(\"last_boot\",DreamTools.boot(c)).commit();\n  if(!ok)DreamTools.log(c,\"Automatický pokus zrušený: zápis ochrany zlyhal.\");\n  return ok;\n }\n static String explanation(String code){\n  switch(code){\n   case \"READY\":return \"Nový automatický pokus je pripravený.\";\n   case \"DISABLED\":return \"Automatické otváranie je vypnuté.\";\n   case \"MISSING_METEOR\":return \"Meteor sa v boxe nenašiel.\";\n   case \"ALREADY_ATTEMPTED\":return \"Pokus po tomto reštarte už prebehol.\";\n   default:return \"Nepodarilo sa rozpoznať štart boxu.\";\n  }\n }\n private LaunchPolicy(){}\n}\n","app/src/main/java/sk/meteor/dream/BootReceiver.java":"package sk.meteor.dream;\nimport android.content.*;\npublic final class BootReceiver extends BroadcastReceiver {\n @Override public void onReceive(Context c,Intent i){\n  if(!Intent.ACTION_BOOT_COMPLETED.equals(i.getAction()))return;\n  DreamTools.prefs(c).edit().putString(\"boot_generation\",java.util.UUID.randomUUID().toString()).remove(\"used_token\").remove(\"last_boot\").remove(\"observed_elapsed\").commit();\n  DreamTools.log(c,\"BOOT_COMPLETED: nový pokus povolený; boot_count=\"+DreamTools.boot(c)+\". Meteor sa otvorí až cez šetrič.\");\n }\n}\n","app/src/main/java/sk/meteor/dream/StopRules.java":"package sk.meteor.dream;\nimport java.text.Normalizer;\nimport java.util.Locale;\npublic final class StopRules {\n static String norm(String s){return Normalizer.normalize(s==null?\"\":s,Normalizer.Form.NFD).replaceAll(\"\\\\p{M}\",\"\").toLowerCase(Locale.ROOT).replaceAll(\"\\\\s+\",\" \").trim();}\n static boolean settings(String p){return \"com.android.tv.settings\".equals(p)||\"com.android.settings\".equals(p);}\n static boolean target(String t){String s=norm(t).replace(\" \",\"\");return s.contains(\"sweet.tv\")||s.contains(\"tv.sweet.tvplayer.inext\");}\n static boolean stop(String t){String s=norm(t);return s.equals(\"vynutit zastavenie\")||s.equals(\"vynutit zastaveni\")||s.equals(\"force stop\")||s.equals(\"kenyszeritett leallitas\")||s.equals(\"kenyszerleallitas\");}\n static boolean confirm(String t){String s=norm(t);return s.equals(\"ok\")||s.equals(\"ano\")||s.equals(\"yes\")||s.equals(\"igen\");}\n static boolean prompt(String t){String s=norm(t);return s.contains(\"force stop\")||s.contains(\"vynutit\")||s.contains(\"zastaven\")||s.contains(\"zastavit\")||s.contains(\"leallit\")||s.contains(\"misbehave\")||s.contains(\"nespravne\");}\n static boolean cancel(String t){String s=norm(t);return s.equals(\"zrusit\")||s.equals(\"cancel\")||s.equals(\"megse\")||s.equals(\"storno\");}\n static boolean open(String t){String s=norm(t);return s.equals(\"otvorit\")||s.equals(\"otevrit\")||s.equals(\"open\")||s.equals(\"megnyitas\");}\n static boolean allowConfirm(int stage,boolean settings,boolean verified,boolean targetVisible,boolean forcePrompt,boolean ok,boolean cancel){\n  return stage==1&&settings&&verified&&targetVisible&&forcePrompt&&ok&&cancel;\n }\n private StopRules(){}\n}\n","app/src/main/java/sk/meteor/dream/SweetStopService.java":"package sk.meteor.dream;\nimport android.accessibilityservice.AccessibilityService;\nimport android.accessibilityservice.AccessibilityServiceInfo;\nimport android.content.*;\nimport android.net.Uri;\nimport android.os.*;\nimport android.provider.Settings;\nimport android.view.accessibility.*;\nimport android.widget.Toast;\nimport java.util.*;\npublic final class SweetStopService extends AccessibilityService {\n private static SweetStopService active;\n private final Handler h=new Handler(Looper.getMainLooper());\n private boolean armed,wasSettings,targetVerified,pollScheduled;\n private int stage;\n private long deadline,requestedAt,confirmedAt;\n private String lastDiagnostic=\"\";\n private final Runnable poll=()->{pollScheduled=false;inspect();};\n private final Runnable timeout=()->expire();\n public static boolean available(){return active!=null;}\n public static boolean begin(Context caller,boolean explicit){\n  SweetStopService s=active;\n  if(s==null||(!explicit&&!DreamTools.prefs(caller).getBoolean(\"stop_sweet\",false)))return false;\n  return s.startRequest();\n }\n @Override protected void onServiceConnected(){\n  active=this;\n  AccessibilityServiceInfo info=getServiceInfo();\n  if(info!=null){info.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;setServiceInfo(info);}\n  DreamTools.log(this,\"Prístupnosť 0.1.4 pripojená; podpora viacerých panelov. Bez požiadavky nevykonáva kroky.\");\n }\n private boolean startRequest(){\n  if(armed)return false;\n  try{getPackageManager().getApplicationInfo(\"tv.sweet.tvplayer.inext\",0);}catch(Exception e){DreamTools.log(this,\"SWEET.TV nenájdená; postup preskočený.\");return false;}\n  armed=true;wasSettings=false;targetVerified=false;stage=0;lastDiagnostic=\"\";\n  requestedAt=SystemClock.elapsedRealtime();deadline=requestedAt+20000L;\n  h.postDelayed(timeout,20000L);\n  try{\n   startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse(\"package:tv.sweet.tvplayer.inext\")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));\n   DreamTools.log(this,\"Spustený jednorazový postup zastavenia iba SWEET.TV.\");queue();return true;\n  }catch(Exception e){cancel(\"Detail SWEET.TV sa neotvoril.\");return false;}\n }\n private void queue(){if(armed&&!pollScheduled){pollScheduled=true;h.postDelayed(poll,300L);}}\n private void expire(){if(!armed)return;cancel(\"Časový limit vo fáze \"+stage+\"; zastavenie nepotvrdené. Meteor automaticky neotváram, aby nezakryl potvrdenie.\");Toast.makeText(this,\"Postup sa nedokončil. Potvrď alebo zruš systémové okno ručne.\",Toast.LENGTH_LONG).show();}\n @Override public void onAccessibilityEvent(AccessibilityEvent e){if(armed)queue();}\n private String text(AccessibilityNodeInfo n){\n  CharSequence t=n.getText(),d=n.getContentDescription();\n  return (t==null?\"\":t.toString())+\" \"+(d==null?\"\":d.toString());\n }\n private boolean matches(String text,int kind){\n  if(kind==0)return StopRules.stop(text);\n  if(kind==1)return StopRules.confirm(text);\n  if(kind==2)return StopRules.target(text);\n  if(kind==3)return StopRules.prompt(text);\n  if(kind==4)return StopRules.cancel(text);\n  return StopRules.open(text);\n }\n private AccessibilityNodeInfo find(AccessibilityNodeInfo n,int kind,int depth){\n  if(n==null||depth>30)return null;\n  // Check text and contentDescription separately: concatenating both duplicates\n  // labels on some TV widgets and breaks exact action-name matching.\n  String t=n.getText()==null?\"\":n.getText().toString();\n  String d=n.getContentDescription()==null?\"\":n.getContentDescription().toString();\n  if(n.isVisibleToUser()&&(matches(t,kind)||matches(d,kind)))return n;\n  for(int k=0;k<n.getChildCount();k++){AccessibilityNodeInfo x=find(n.getChild(k),kind,depth+1);if(x!=null)return x;}\n  return null;\n }\n private boolean settingsRoot(AccessibilityNodeInfo n){return n!=null&&n.getPackageName()!=null&&StopRules.settings(n.getPackageName().toString());}\n private List<AccessibilityNodeInfo> roots(AccessibilityNodeInfo activeRoot){\n  List<AccessibilityNodeInfo> result=new ArrayList<>();\n  if(settingsRoot(activeRoot))result.add(activeRoot);\n  for(AccessibilityWindowInfo w:getWindows()){\n   AccessibilityNodeInfo n=w.getRoot();\n   if(settingsRoot(n))result.add(n);\n  }\n  return result;\n }\n private boolean has(List<AccessibilityNodeInfo> roots,int kind){for(AccessibilityNodeInfo n:roots)if(find(n,kind,0)!=null)return true;return false;}\n private AccessibilityNodeInfo action(AccessibilityNodeInfo n){\n  AccessibilityNodeInfo fallback=n;\n  for(int k=0;n!=null&&k<6;k++,n=n.getParent())if(n.isClickable())return n;\n  return fallback;\n }\n private boolean enabled(AccessibilityNodeInfo n){AccessibilityNodeInfo a=action(n);return a!=null&&a.isEnabled();}\n private boolean click(AccessibilityNodeInfo n){\n  AccessibilityNodeInfo a=action(n);\n  return a!=null&&a.isEnabled()&&a.isVisibleToUser()&&a.performAction(AccessibilityNodeInfo.ACTION_CLICK);\n }\n private void inspect(){try{inspectUnsafe();}catch(Exception e){cancel(\"Chyba čítania nastavení; ďalšie kroky zrušené: \"+e.getClass().getSimpleName());}}\n private void inspectUnsafe(){\n  if(!armed)return;\n  AccessibilityNodeInfo root=getRootInActiveWindow();\n  boolean settings=settingsRoot(root);\n  if(!settings){\n   if(wasSettings&&root!=null){cancel(\"Odchod zo systémových nastavení: pokus zrušený.\");return;}\n   if(SystemClock.elapsedRealtime()>=deadline){cancel(\"Systém neposkytol okno nastavení; nič ďalšie nestláčam.\");return;}\n   queue();return;\n  }\n  wasSettings=true;\n  List<AccessibilityNodeInfo> visible=roots(root);\n  boolean target=has(visible,2),prompt=has(visible,3);\n  AccessibilityNodeInfo yes=find(root,1,0),no=find(root,4,0),button=find(root,0,0);\n  String diag=\"Fáza=\"+stage+\"; panely=\"+visible.size()+\"; cieľ=\"+target+\"; potvrdenie=\"+prompt+\"; OK=\"+(yes!=null)+\"; Zrušiť=\"+(no!=null);\n  if(!diag.equals(lastDiagnostic)){DreamTools.log(this,diag);lastDiagnostic=diag;}\n  if(SystemClock.elapsedRealtime()>=deadline){\n   cancel(\"Časový limit vo fáze \"+stage+\"; zastavenie nepotvrdené. Meteor automaticky neotváram, aby nezakryl prípadné potvrdenie.\");\n   Toast.makeText(this,\"Postup sa nedokončil. Potvrď alebo zruš systémové okno ručne.\",Toast.LENGTH_LONG).show();return;\n  }\n  if(stage==0&&target&&button!=null){\n   if(!enabled(button)){complete(\"Vynútiť zastavenie je neaktívne; stav procesu sa priamo nemeral.\");return;}\n   if(click(button)){stage=1;targetVerified=true;DreamTools.log(this,\"Stlačené Vynútiť zastavenie v overenom detaile SWEET.TV.\");}\n  }else if(StopRules.allowConfirm(stage,settings,targetVerified,target,prompt,yes!=null,no!=null)){\n   if(click(yes)){stage=2;confirmedAt=SystemClock.elapsedRealtime();DreamTools.log(this,\"Potvrdenie OK zastavenia SWEET.TV odoslané.\");}\n  }else if(stage==2&&SystemClock.elapsedRealtime()-confirmedAt>=700L&&target&&yes==null&&has(visible,5)){\n   if(button==null||!enabled(button)){complete(\"Po potvrdení OK detail SWEET.TV už neponúka aktívne Vynútiť zastavenie.\");return;}\n  }else if(stage==0&&SystemClock.elapsedRealtime()-requestedAt>=1500L&&target&&button==null&&yes==null&&has(visible,5)){\n   complete(\"V detaile SWEET.TV chýba Vynútiť zastavenie; stav procesu nepotvrdený.\");return;\n  }\n  queue();\n }\n private void complete(String result){\n  cancel(result);\n  try{Intent i=DreamTools.meteor(this);if(i!=null){startActivity(i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));DreamTools.log(this,\"Po dokončení postupu odoslaná požiadavka na Meteor.\");}}catch(Exception e){DreamTools.log(this,\"Meteor sa neotvoril: \"+e.getClass().getSimpleName());}\n }\n private void cancel(String result){armed=false;pollScheduled=false;h.removeCallbacks(poll);h.removeCallbacks(timeout);DreamTools.log(this,result);}\n @Override public void onInterrupt(){if(armed)cancel(\"Prístupnosť prerušená; pokus zrušený.\");}\n @Override public void onDestroy(){if(armed)cancel(\"Prístupnosť vypnutá; pokus zrušený.\");if(active==this)active=null;super.onDestroy();}\n}\n","app/src/main/java/sk/meteor/dream/MeteorDream.java":"package sk.meteor.dream;\nimport android.service.dreams.DreamService;\nimport android.content.Intent;\nimport android.graphics.Color;\nimport android.os.*;\nimport android.view.*;\nimport android.widget.*;\npublic final class MeteorDream extends DreamService {\n private final Handler h=new Handler(Looper.getMainLooper());\n private TextView text;\n private boolean attempted;\n private final Runnable launch=()->open(false);\n private final Runnable handoff=()->{DreamTools.log(this,\"Ukončujem šetrič pri chránenej zmene obrazovky.\");finish();};\n @Override public void onAttachedToWindow(){\n  super.onAttachedToWindow();setInteractive(true);setFullscreen(true);setScreenBright(true);\n  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(32,24,32,24);root.setBackgroundColor(0xff091426);\n  text=new TextView(this);text.setTextColor(Color.WHITE);text.setTextSize(23);root.addView(text);\n  Button go=new Button(this);go.setText(\"Otvoriť Meteor teraz\");root.addView(go);go.setOnClickListener(v->{h.removeCallbacks(launch);open(true);});\n  Button stop=new Button(this);stop.setText(\"Zrušiť / ukončiť šetrič\");root.addView(stop);stop.setOnClickListener(v->{cancelTimers();finish();});\n  setContentView(root);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);stop.requestFocus();\n }\n @Override public void onDreamingStarted(){\n  super.onDreamingStarted();attempted=false;\n  String reason=LaunchPolicy.reason(this);\n  DreamTools.log(this,\"Štart šetriča 0.1.4; dôvod=\"+reason+\"; token=\"+LaunchPolicy.token(this)+\"; použitý=\"+DreamTools.prefs(this).getString(\"used_token\",\"žiadny\")+\"; elapsed_ms=\"+SystemClock.elapsedRealtime());\n  if(\"READY\".equals(reason)){text.setText(\"METEOR · otvorenie o 1 sekundu\");h.postDelayed(launch,1000L);}\n  else text.setText(\"METEOR ŠETRIČ\\n\"+LaunchPolicy.explanation(reason)+\"\\nMeteor môžeš otvoriť ručne tlačidlom.\");\n }\n @SuppressWarnings(\"deprecation\") private void open(boolean manual){\n  if(attempted&&!manual)return;\n  Intent i=DreamTools.meteor(this);if(i==null){text.setText(\"Meteor nie je dostupný.\");return;}\n  if(!manual&&!LaunchPolicy.claim(this))return;\n  attempted=true;PowerManager.WakeLock transfer=null;\n  try{\n   PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);\n   if(pm==null)throw new IllegalStateException();\n   transfer=pm.newWakeLock(PowerManager.SCREEN_DIM_WAKE_LOCK|PowerManager.ACQUIRE_CAUSES_WAKEUP|PowerManager.ON_AFTER_RELEASE,\"meteor:DreamHandoff\");\n   transfer.setReferenceCounted(false);transfer.acquire(5000L);\n   final PowerManager.WakeLock guard=transfer;\n   final android.content.Context app=getApplicationContext();\n   new Handler(Looper.getMainLooper()).postDelayed(()->{if(guard.isHeld())guard.release();DreamTools.log(app,\"Ochrana prechodu uvoľnená. \"+DreamTools.power(app));},2000L);\n   boolean stop=SweetStopService.begin(this,false);\n   if(!stop){startActivity(i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));DreamTools.log(this,\"Požiadavka na Meteor odoslaná; ručný=\"+manual+\"; voliteľný postup SWEET.TV nebol spustený.\");}\n   else DreamTools.log(this,\"Obrazovku odovzdávam systémovému detailu SWEET.TV; Meteor otvorí služba po postupe.\");\n   text.setText(\"Odovzdávam obrazovku…\");h.postDelayed(handoff,350L);\n  }catch(Exception e){if(transfer!=null&&transfer.isHeld())transfer.release();DreamTools.log(this,\"Prechod zlyhal: \"+e.getClass().getSimpleName());text.setText(\"Prechod sa nepodaril: \"+e.getClass().getSimpleName()+\". Šetrič môžeš ukončiť ručne.\");}\n }\n private void cancelTimers(){h.removeCallbacks(launch);h.removeCallbacks(handoff);}\n @Override public boolean dispatchKeyEvent(KeyEvent e){if(e.getKeyCode()==KeyEvent.KEYCODE_BACK){cancelTimers();finish();return true;}return super.dispatchKeyEvent(e);}\n @Override public void onDreamingStopped(){cancelTimers();DreamTools.log(this,\"Systém zastavil šetrič. \"+DreamTools.power(this));super.onDreamingStopped();}\n @Override public void onDetachedFromWindow(){cancelTimers();super.onDetachedFromWindow();}\n @Override public void onDestroy(){cancelTimers();super.onDestroy();}\n}\n","app/src/main/java/sk/meteor/dream/MainActivity.java":"package sk.meteor.dream;\nimport android.app.*;\nimport android.content.*;\nimport android.content.res.ColorStateList;\nimport android.graphics.Color;\nimport android.os.Bundle;\nimport android.provider.Settings;\nimport android.widget.*;\npublic final class MainActivity extends Activity {\n private LinearLayout layout;private TextView status;\n private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}\n private TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setPadding(0,dp(8),0,dp(8));layout.addView(t);return t;}\n private void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setMinHeight(dp(52));b.setTextColor(Color.WHITE);b.setBackgroundTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_focused},new int[]{}},new int[]{0xffa65b00,0xff203653}));layout.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->r.run());}\n private void settings(String action){try{startActivity(new Intent(action));}catch(Exception e){status.setText(\"Systém túto obrazovku neposkytol.\");}}\n @Override public void onCreate(Bundle b){\n  super.onCreate(b);ScrollView scroll=new ScrollView(this);scroll.setPadding(dp(24),dp(16),dp(24),dp(24));layout=new LinearLayout(this);layout.setOrientation(1);scroll.addView(layout);setContentView(scroll);\n  label(\"METEOR ŠETRIČ · test 0.1.4\",25);\n  label(\"Otvorenie Meteoru cez šetrič najviac raz po štarte boxu. Systémový čas 5 minút sa nemení. Voliteľné zastavenie SWEET.TV je testovacia funkcia cez jej systémový detail.\",17);\n  status=label(\"\",16);\n  button(\"1. Otvoriť systémový výber šetriča\",()->settings(Settings.ACTION_DREAM_SETTINGS));\n  Switch enabled=new Switch(this);enabled.setText(\"Automaticky skúsiť otvoriť Meteor\");enabled.setChecked(DreamTools.prefs(this).getBoolean(\"enabled\",true));layout.addView(enabled);enabled.setOnCheckedChangeListener((v,x)->{DreamTools.prefs(this).edit().putBoolean(\"enabled\",x).apply();refresh();});\n  button(\"2. Povoliť nový pokus na skúšku\",()->{DreamTools.prefs(this).edit().remove(\"used_token\").remove(\"last_boot\").commit();DreamTools.log(this,\"Ručne povolený nový skúšobný pokus.\");refresh();});\n  label(\"VOLITEĽNÉ ZASTAVENIE SWEET.TV\",20);\n  label(\"Vyžaduje ručne zapnúť službu Meteor · zastavenie SWEET.TV v Prístupnosti. Služba pri jednorazovom pokuse prečíta iba okno systémových nastavení a skúsi stlačiť Vynútiť zastavenie a potvrdenie pre SWEET.TV. Nič neodinštaluje ani nemaže. Iné aplikácie neovláda. Bez požiadavky nevykonáva kroky; limit pokusu 20 s. Výsledok treba overiť na boxe.\",16);\n  button(\"3. Otvoriť Prístupnosť / Zjednodušenie ovládania\",()->settings(Settings.ACTION_ACCESSIBILITY_SETTINGS));\n  Switch stop=new Switch(this);stop.setText(\"Pred Meteorom skúsiť zastaviť SWEET.TV\");stop.setChecked(DreamTools.prefs(this).getBoolean(\"stop_sweet\",false));layout.addView(stop);stop.setOnCheckedChangeListener((v,x)->{DreamTools.prefs(this).edit().putBoolean(\"stop_sweet\",x).apply();refresh();});\n  button(\"4. Skúsiť zastaviť SWEET.TV a otvoriť Meteor teraz\",()->{if(!SweetStopService.begin(this,true)){status.setText(\"Postup sa nespustil. Zapni našu službu v Prístupnosti a over, že je SWEET.TV nainštalovaná.\");}});\n  button(\"Kopírovať priebeh testu\",()->{String s=DreamTools.prefs(this).getString(\"history\",\"\");((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText(\"Meteor priebeh\",s));Toast.makeText(this,\"Priebeh skopírovaný\",Toast.LENGTH_SHORT).show();});\n  button(\"Otvoriť Meteor ručne\",()->{try{Intent i=DreamTools.meteor(this);if(i!=null)startActivity(i);}catch(Exception e){status.setText(\"Meteor sa neotvoril.\");}});\n  button(\"Nastavenia Androidu\",()->settings(Settings.ACTION_SETTINGS));\n  label(\"Po aktualizácii raz otvor túto aplikáciu. BOOT_COMPLETED iba obnoví povolenie na pokus; neobchádza systémový čas šetriča. Službu možno kedykoľvek vypnúť v Prístupnosti. Pre návrat k pôvodnému šetriču vyber Farby.\",16);\n }\n private void refresh(){\n  status.setText(\"Meteor: \"+(DreamTools.meteor(this)!=null?\"nájdený\":\"nenájdený\")+\"\\n\"+LaunchPolicy.explanation(LaunchPolicy.reason(this))+\"\\nPrístupnosť: \"+(SweetStopService.available()?\"pripojená\":\"nepripojená\")+\"\\nZastavenie SWEET.TV: \"+(DreamTools.prefs(this).getBoolean(\"stop_sweet\",false)?\"zapnuté\":\"vypnuté\")+\"\\nboot_count=\"+DreamTools.boot(this)+\"; token=\"+LaunchPolicy.token(this)+\"\\n\\nPRIEBEH TESTU\\n\"+DreamTools.prefs(this).getString(\"history\",\"\"));\n }\n @Override protected void onResume(){super.onResume();if(status!=null)refresh();}\n}\n","app/src/main/res/xml/sweet_stop.xml":"<accessibility-service xmlns:android=\"http://schemas.android.com/apk/res/android\"\n android:accessibilityEventTypes=\"typeWindowStateChanged|typeWindowContentChanged|typeWindowsChanged\"\n android:packageNames=\"com.android.tv.settings,com.android.settings\"\n android:accessibilityFeedbackType=\"feedbackGeneric\"\n android:accessibilityFlags=\"flagRetrieveInteractiveWindows\"\n android:notificationTimeout=\"200\"\n android:canRetrieveWindowContent=\"true\"\n android:description=\"@string/sweet_stop_description\"\n android:settingsActivity=\"sk.meteor.dream.MainActivity\"/>","app/src/main/res/values/sweet_stop.xml":"<resources><string name=\"sweet_stop_description\">Voliteľný jednorazový postup iba pre SWEET.TV: otvorí jej systémový detail, skúsi Vynútiť zastavenie a potvrdenie, potom otvorí Meteor. Potrebuje čítať a ovládať okno nastavení. Nečíta obsah iných aplikácií, neodosiela údaje a bez požiadavky nevykonáva kroky. Limit 20 sekúnd. Vypnutie v Prístupnosti.</string></resources>","tests/UpgradeRulesTest.java":"package sk.meteor.dream;\npublic final class UpgradeRulesTest{\n static int n;static void check(boolean b){n++;if(!b)throw new AssertionError(\"check \"+n);}\n public static void main(String[] a){\n  check(\"READY\".equals(LaunchRules.reason(true,true,\"3:bootA\",\"2:bootB\")));\n  check(\"ALREADY_ATTEMPTED\".equals(LaunchRules.reason(true,true,\"3:bootA\",\"3:bootA\")));\n  check(\"READY\".equals(LaunchRules.reason(true,true,\"3:bootB\",\"3:bootA\")));\n  check(\"DISABLED\".equals(LaunchRules.reason(false,true,\"3:bootB\",\"\")));\n  check(\"MISSING_METEOR\".equals(LaunchRules.reason(true,false,\"3:bootB\",\"\")));\n  check(\"UNKNOWN_BOOT\".equals(LaunchRules.reason(true,true,\"\",\"\")));\n  check(StopRules.settings(\"com.android.tv.settings\"));check(!StopRules.settings(\"tv.sweet.tvplayer.inext\"));\n  check(StopRules.target(\"SWEET.TV\"));check(!StopRules.target(\"YouTube\"));\n  check(StopRules.stop(\"Vynútiť zastavenie\"));check(StopRules.stop(\"Force stop\"));\n  check(StopRules.confirm(\"OK\"));check(!StopRules.confirm(\"Odinštalovať\"));\n  check(!StopRules.stop(\"Vypnúť\"));check(!StopRules.confirm(\"Zrušiť\"));\n  check(StopRules.prompt(\"Ak aplikáciu vynútite zastaviť, môže fungovať nesprávne.\"));\n  check(StopRules.cancel(\"Zrušiť\"));check(StopRules.open(\"Otvoriť\"));\n  check(StopRules.allowConfirm(1,true,true,true,true,true,true));\n  check(!StopRules.allowConfirm(0,true,true,true,true,true,true));\n  check(!StopRules.allowConfirm(2,true,true,true,true,true,true));\n  check(!StopRules.allowConfirm(1,false,true,true,true,true,true));\n  check(!StopRules.allowConfirm(1,true,false,true,true,true,true));\n  check(!StopRules.allowConfirm(1,true,true,false,true,true,true));\n  check(!StopRules.allowConfirm(1,true,true,true,false,true,true));\n  check(!StopRules.allowConfirm(1,true,true,true,true,false,true));\n  check(!StopRules.allowConfirm(1,true,true,true,true,true,false));\n  System.out.println(n+\" boot/token/target/action checks passed\");\n }\n}\n"}''')
